213			t := &findings[i]
214			if t.Verdict != "below_minimum" || fixNecessityRank(t.FixNecessity) == 0 {
215				return nil, fmt.Sprintf("below_minimum_ref の参照先 (%d 回目の id %d) は、必要度を判定して下限未満にした指摘ではありません (verdict %q / fix_necessity %q)",
216					ref.Run, ref.Finding, t.Verdict, t.FixNecessity)
217			}
218			return t, ""
219		}
220		return nil, fmt.Sprintf("below_minimum_ref の finding %d は %d 回目の findings にありません", ref.Finding, ref.Run)
221	}
222	
223	// recordBelowMinimumRefProblems は指摘 1 件の below_minimum_ref と、それに関わるキーを検査する。
224	func recordBelowMinimumRefProblems(doc *recordDoc, ri int, fd recordFinding) []string {
225		var problems []string
226		add := func(format string, args ...any) {
227			problems = append(problems, fmt.Sprintf(format, args...))
228		}
229		ref := fd.BelowMinimumRef
230		if ref == nil {
231			if fd.Origin == "prior_below_minimum" {
232				add("origin が prior_below_minimum なのに below_minimum_ref がありません (足した指摘は、前の回のどの指摘かを書く)")
233			}
234			return problems
235		}
236		target, msg := belowMinimumRefTarget(doc, ri, ref)
237		if msg != "" {
238			add("%s", msg)
239		}
240		switch ref.LineCheck {
241		case "holds", "not-holds", "unverifiable":
242		default:
243			add("below_minimum_ref.line_check は holds / not-holds / unverifiable のいずれか: %q", ref.LineCheck)
244		}
245		if ref.LineReason == "" {
246			add("below_minimum_ref.line_reason がありません (対象の行が変わっていないかの結果の理由)")
247		}
248		if !judgmentOmitted(fd) {
249			return problems
250		}
251		// 判定を省略した指摘 (A3・B2)。分類・被害者・帰結・根拠の検証・ゲート・必要度は書かない。
252		// 書いてあると、参照先の値と、この指摘の値のどちらを読むのかが決まらない。
253		for _, kv := range []struct {
254			key     string
255			written bool
256		}{
257			{"category", fd.Category != ""},
258			{"audience", fd.Audience != ""},
259			{"audience_initial", fd.AudienceInitial != ""},
260			{"consequence", fd.Consequence != recordConsequence{}},
261			{"premise_check", fd.PremiseCheck != recordPremise{}},
262			{"gates_fired", len(fd.GatesFired) > 0},
263			{"prior_defect", fd.PriorDefect != nil},
264			{"fix_necessity", fd.FixNecessity != ""},
265			{"fix_necessity_reason", fd.FixNecessityReason != nil},
266		} {
267			if kv.written {
268				add("判定を省略した指摘 (below_minimum_ref.line_check が holds) では %s を書かない (参照先の指摘のものを読む)", kv.key)
269			}
270		}
271		if target == nil {
272			return problems
273		}
274		// D12: 参照先の必要度が、この回の下限以上なら採択 (A3)、満たなければ下限未満 (B2)。
275		want := "adopted"
276		if fixNecessityBelow(target.FixNecessity, doc.Runs[ri].MinFixNecessity) {
277			want = "below_minimum"
278		}
279		if fd.Verdict != want {
280			minimum := doc.Runs[ri].MinFixNecessity
281			if minimum == "" {
282				minimum = "無し"
283			}
284			add("判定を省略した指摘の verdict は、参照先の必要度 %s と回の下限 %s から %s に決まりますが、%q です",
285				target.FixNecessity, minimum, want, fd.Verdict)
286		}
287		return problems
288	}
289	
290	// recordPriorBelowMinimumProblems は、回 (添字 ri) に足すべき下限未満の指摘が、足されているかを
291	// 検査する。それより前の回の、残っている下限未満の指摘 (必要度を判定して下限未満にした指摘で、
292	// この回より前の回の指摘が参照して、判定し直しても採択にしてもいないもの) のうち、必要度がこの回の
293	// 下限以上のもの (下限が無い回ではすべて) は、この回の指摘として足す (record-schema.md の
294	// 「下限未満の指摘の参照」)。足し忘れると、下限を下げても、その指摘は採択にならず直されないまま残る。
295	// 足したかどうかは、この回の指摘の below_minimum_ref が参照しているかで見る。呼び出し元は、
296	// 記録の最後の回についてだけ呼ぶ。
297	func recordPriorBelowMinimumProblems(doc *recordDoc, ri int) []string {
298		type key struct{ run, finding int }
299		remaining := map[key]string{} // 残っている下限未満の指摘と、その必要度
300		var order []key
301		for pi := 0; pi < ri; pi++ {
302			for _, fd := range doc.Runs[pi].Findings {
303				if ref := fd.BelowMinimumRef; ref != nil && !(judgmentOmitted(fd) && fd.Verdict == "below_minimum") {
304					// 判定し直したか、採択 (A3) にした。参照先は残っていない。
305					delete(remaining, key{ref.Run, ref.Finding})
306				}
307				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
308					k := key{pi + 1, fd.ID}
309					remaining[k] = fd.FixNecessity
310					order = append(order, k)
311				}
312			}
313		}
314		referenced := map[key]bool{}
315		for _, fd := range doc.Runs[ri].Findings {
316			if ref := fd.BelowMinimumRef; ref != nil {
317				referenced[key{ref.Run, ref.Finding}] = true
318			}
319		}
320		minimum := doc.Runs[ri].MinFixNecessity
321		var problems []string
322		for _, k := range order {
323			necessity, ok := remaining[k]
324			if !ok || referenced[k] || fixNecessityBelow(necessity, minimum) {
325				continue
326			}
327			// 下限が列挙に無い値のときは、比べられないので報告しない (列挙の誤りは別に報告する)。
328			if minimum != "" && fixNecessityRank(minimum) == 0 {
329				continue
330			}
331			// 「無い」には「のに」が、「以上」には「なのに」が付くので、句ごとに「のに」まで書く。
332			limit := "この回に下限が無いのに"
333			if minimum != "" {
334				limit = "この回の下限 " + minimum + " 以上なのに"
335			}
336			problems = append(problems, fmt.Sprintf(
337				"残っている下限未満の指摘 (%d 回目の id %d。必要度 %s) が、%s、この回の findings に足されていません (origin: prior_below_minimum と below_minimum_ref を書いて足す)",
338				k.run, k.finding, necessity, limit))
339		}
340		return problems
341	}
342	
343	// findingFixNecessity は指摘の必要度を返す。判定を省略した指摘は、参照先の必要度。
344	// 分からなければ空。
345	func findingFixNecessity(doc *recordDoc, ri int, fd recordFinding) string {
346		if !judgmentOmitted(fd) {
347			return fd.FixNecessity
348		}
349		if target, _ := belowMinimumRefTarget(doc, ri, fd.BelowMinimumRef); target != nil {
350			return target.FixNecessity
351		}
352		return ""
353	}
354	
355	// renderFixNecessityCounts は推移の表の必要度の 3 列 (Must・Should・Could) を返す。
356	// 判定に関わらず、その回で必要度が分かる指摘を数える。fix_necessity_reason を必須にする回
357	// (recordFixNecessityFirstRun) より前の回 (必須にする回が無い記録ではすべての回) は「—」にする。0 と書くと、
358	// 必要度を判定して 0 件だったように読めるため。
359	func renderFixNecessityCounts(doc *recordDoc, ri, firstRun int) []string {
360		if firstRun < 0 || ri < firstRun {
361			return []string{"—", "—", "—"}
362		}
363		counts := map[string]int{}
364		for _, fd := range doc.Runs[ri].Findings {
365			counts[findingFixNecessity(doc, ri, fd)]++
366		}
367		return []string{
368			fmt.Sprint(counts["must"]), fmt.Sprint(counts["should"]), fmt.Sprint(counts["could"]),
369		}

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.
